// Build bridge used by `cf build`: cf delegates static-site packaging to
// Wrangler, which copies this directory into .cloudflare/output/v0/. It must
// point at the already-built zfb output (`pnpm build` at the repository root).
// Shape generated by `cf init` (cf@1.0.0-beta.28, wrangler 4.158.0) and
// reviewed; it may change while the cf configuration format is in beta.
import { defineWranglerConfig } from "wrangler/experimental-config";

export default defineWranglerConfig({
  assetsDirectory: "dist",
});
